PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "drivers" (
"driverId" TEXT,
  "url" TEXT,
  "GivenName" TEXT,
  "FamilyName" TEXT,
  "DateOfBirth" TEXT,
  "Nationality" TEXT
);
CREATE TABLE IF NOT EXISTS "constructors" (
"year" INTEGER,
  "constructorId" TEXT,
  "url" TEXT,
  "Name" TEXT,
  "Nationality" TEXT
);
CREATE TABLE IF NOT EXISTS "results" (
"Season" INTEGER,
  "Round" INTEGER,
  "CircuitID" TEXT,
  "Position" INTEGER,
  "Points" REAL,
  "DriverID" TEXT,
  "Code" TEXT,
  "PermanentNumber" INTEGER,
  "GivenName" TEXT,
  "FamilyName" TEXT,
  "DateOfBirth" TEXT,
  "Nationality" TEXT,
  "ConstructorName" TEXT,
  "ConstructorNationality" TEXT,
  "Grid" INTEGER,
  "Laps" INTEGER,
  "Status" TEXT,
  "Time" REAL,
  "FastestLapTime" TEXT,
  "FastestLapLap" INTEGER,
  "AverageSpeed" REAL
);
CREATE TABLE IF NOT EXISTS "driver_standings" (
"season" INTEGER,
  "round" INTEGER,
  "position" INTEGER,
  "points" REAL,
  "wins" INTEGER,
  "driverId" TEXT
);
CREATE TABLE IF NOT EXISTS "constructor_standings" (
"season" INTEGER,
  "round" INTEGER,
  "position" INTEGER,
  "points" REAL,
  "wins" INTEGER,
  "constructorId" TEXT
);
CREATE TABLE IF NOT EXISTS "pitstops" (
"season" INTEGER,
  "round" INTEGER,
  "circuitId" TEXT,
  "driverId" TEXT,
  "stop" INTEGER,
  "lap" INTEGER,
  "duration" REAL
);
CREATE TABLE IF NOT EXISTS "results_history" (
"Season" INTEGER,
  "Round" INTEGER,
  "CircuitID" TEXT,
  "country" TEXT,
  "ConstructorName" TEXT,
  "constructorId" TEXT,
  "ConstructorNationality" TEXT,
  "DriverID" TEXT,
  "DriverName" TEXT,
  "DriverNationality" TEXT,
  "Nationality" TEXT,
  "Position" INTEGER,
  "Points" REAL,
  "Grid" INTEGER,
  "Status" TEXT,
  "AverageSpeed" REAL,
  "DifferenceGridPosition" INTEGER,
  "WonLastRace" INTEGER,
  "WonLast2Races" INTEGER,
  "WonLast3Races" INTEGER,
  "WonLast4Races" INTEGER,
  "WonLast5Races" INTEGER,
  "WonLast6Races" INTEGER,
  "WonLast7Races" INTEGER,
  "WonLast10Races" INTEGER,
  "Top3Last5Races" INTEGER,
  "Top5Last10Races" INTEGER
);
CREATE TABLE IF NOT EXISTS "results_qualy" (
"Season" INTEGER,
  "Round" INTEGER,
  "CircuitID" TEXT,
  "DriverID" TEXT,
  "Code" TEXT,
  "PermanentNumber" INTEGER,
  "GivenName" TEXT,
  "FamilyName" TEXT,
  "DateOfBirth" TEXT,
  "driver_nationality" TEXT,
  "ConstructorID" TEXT,
  "ConstructorName" TEXT,
  "constructor_nationality" TEXT,
  "Q1" TEXT,
  "Q2" TEXT,
  "Q3" TEXT,
  "avg_Q1_time" REAL,
  "avg_Q2_time" REAL,
  "avg_Q3_time" REAL,
  "driver_avg_position" REAL,
  "driver_total_races" REAL,
  "avg_constructor_position" REAL,
  "was_first_last_1" INTEGER,
  "was_first_last_2" INTEGER,
  "was_first_last_3" INTEGER,
  "was_first_last_4" INTEGER,
  "was_first_last_5" INTEGER,
  "was_top3_last_1" INTEGER,
  "was_top3_last_2" INTEGER,
  "was_top3_last_3" INTEGER,
  "was_top3_last_4" INTEGER,
  "was_top3_last_5" INTEGER,
  "was_top5_last_1" INTEGER,
  "was_top5_last_2" INTEGER,
  "was_top5_last_3" INTEGER,
  "was_top5_last_4" INTEGER,
  "was_top5_last_5" INTEGER,
  "was_top8_last_1" INTEGER,
  "was_top8_last_2" INTEGER,
  "was_top8_last_3" INTEGER,
  "was_top8_last_4" INTEGER,
  "was_top8_last_5" INTEGER,
  "was_top10_last_1" INTEGER,
  "was_top10_last_2" INTEGER,
  "was_top10_last_3" INTEGER,
  "was_top10_last_4" INTEGER,
  "was_top10_last_5" INTEGER,
  "was_top15_last_1" INTEGER,
  "was_top15_last_2" INTEGER,
  "was_top15_last_3" INTEGER,
  "was_top15_last_4" INTEGER,
  "was_top15_last_5" INTEGER,
  "Position" INTEGER
);
COMMIT;
